<section id="nwm-sites" class="nwm-sites-section" aria-label="Sitios registrados"><div class="nwm-section-heading"><div><p class="nwm-section-label">Directorio de sitios</p><h2>Sitios registrados <span class="nwm-count"><?= count($sites) ?></span></h2></div><span class="nwm-utc-note">Fechas en UTC</span></div><p class="nwm-section-intro">Revisa la información clave y entra en un sitio para consultar su inventario, historial y opciones.</p>
<?php if($sites): ?>
<div class="nwm-site-filters" hidden data-nwm-filter-controls><div class="nwm-search"><?= $icon('search') ?><label class="nwm-visually-hidden" for="nwm-site-search">Buscar sitios por nombre o URL</label><input id="nwm-site-search" type="search" placeholder="Buscar por nombre o dirección…" autocomplete="off"></div><label class="nwm-visually-hidden" for="nwm-site-state">Filtrar por estado</label><select id="nwm-site-state"><option value="all">Todos los estados</option><option value="review">Requieren revisión</option><option value="recent">Inventario reciente</option><option value="never">Sin comprobar</option></select><button class="nwm-button nwm-button--quiet" type="button" data-nwm-clear-filters>Limpiar</button><span class="nwm-filter-count" role="status" data-nwm-filter-count><?= count($sites) ?> sitios</span></div>
<table class="nwm-site-table"><caption class="nwm-visually-hidden">Información clave por sitio. Entrar abre una ficha independiente.</caption><thead><tr><th scope="col">Sitio</th><th scope="col">Estado</th><th scope="col">Joomla / PHP</th><th scope="col">Actualizaciones<br><small>en caché</small></th><th scope="col">Última comprobación</th><th scope="col">Acceso</th></tr></thead><tbody>
<?php foreach($sites as $row): $state=$states[$row['check_state']??'never_checked']??['Estado desconocido','warning','review'];$summary=$row['inventory_summary']??[];$coverage=$summary['coverage']??[];$brief=static fn($key,$field)=>($coverage[$key]??'')==='denied'?'No compartido':($summary[$key][$field]??'—');$last=$row['checks'][0]??null; ?>
<tr data-nwm-site data-state="<?= $escape($state[2]) ?>" data-search="<?= $escape($row['label'].' '.$row['base_url']) ?>"><th scope="row" class="nwm-row-name"><a href="<?= $escape($siteUrl($row['id'])) ?>" title="<?= $escape($row['label']) ?>"><?= $escape($row['label']) ?></a><span title="<?= $escape($row['base_url']) ?>"><?= $escape($row['base_url']) ?></span></th><td data-label="Estado"><span class="nwm-badge nwm-badge--<?= $state[1] ?>"><?= $escape($state[0]) ?></span></td><td data-label="Joomla / PHP"><span class="nwm-row-version"><?= $escape($brief('joomla','version')) ?></span><small>PHP <?= $escape($brief('runtime','php_version')) ?></small></td><td data-label="Actualizaciones en caché"><?= $escape($brief('updates','total')) ?></td><td data-label="Última comprobación"><time><?= $last?$escape($date($last['checked_at'])):'Sin comprobar' ?></time><small><?= ($row['connection_type']??'https')==='local'?'Este mismo Joomla':'HTTPS remoto' ?></small></td><td class="nwm-row-action"><a class="nwm-button nwm-button--secondary" href="<?= $escape($siteUrl($row['id'])) ?>" aria-label="Entrar en <?= $escape($row['label']) ?>">Entrar<?= $icon('arrow') ?></a></td></tr>
<?php endforeach; ?></tbody></table><div class="nwm-empty" data-nwm-no-results hidden><h3>No hay coincidencias</h3><p>Prueba otro nombre, dirección o estado, o limpia los filtros.</p></div>
<?php else: ?><div class="nwm-empty"><span><?= $icon('server') ?></span><h3>Tu primer sitio empieza aquí</h3><p>Registra un Joomla y entra en su ficha para consultar la información que comparta.</p><?php if($canCreate): ?><a class="nwm-button nwm-button--primary" href="<?= $escape($pageUrl('add')) ?>">Añadir el primer sitio<?= $icon('arrow') ?></a><?php else: ?><p>Un administrador puede completar la vinculación.</p><?php endif; ?></div><?php endif; ?></section>
